"""工序反馈系统.py —— 单文件自释放部署包（工序反馈追溯系统）。

双击运行（或 `python 工序反馈系统.py`）后：
  1) 把内嵌的 server.py + 4 个网页释放到本文件所在目录
     已存在的文件跳过、不覆盖（避免破坏你已有的本地修改）；
  2) 释放完直接启动服务，浏览器打开 http://127.0.0.1:8000/ 即可使用，
     车间其它电脑用 http://<本机IP>:8000/ 访问。关掉这个窗口即停止服务。

只想释放文件、不想启动服务：
    python 工序反馈系统.py --no-start
想换端口：
    python 工序反馈系统.py 9000
正式部署、不要示例数据：
    python 工序反馈系统.py --no-seed
"""
from __future__ import annotations

import base64
import gzip
import os
import sys

DEFAULT_PORT = 8000

# 内嵌文件：(相对路径, base64(gzip(内容)))
_FILES = [
    ('server.py', ''),
    ('process-feedback-matrix.html', ''),
    ('feedback-list.html', ''),
    ('feedback-entry.html', ''),
    ('cutline-chart.html', ''),
    ('settings.html', ''),
]


def _say(msg):
    """打印一行。控制台编码不支持某些汉字时降级为 '?'，不让 print 抛异常中断部署。"""
    try:
        print(msg)
    except UnicodeEncodeError:
        enc = (sys.stdout.encoding or "utf-8")
        print(msg.encode(enc, "replace").decode(enc, "replace"))


def _release(target_dir):
    """把内嵌文件释放到 target_dir；已存在的同名文件跳过、不覆盖。

    返回 (新建列表, 跳过列表, 失败列表[(路径, 原因)])。
    """
    created, skipped, failed = [], [], []
    for rel, b64 in _FILES:
        dest = os.path.join(target_dir, rel)
        parent = os.path.dirname(dest)
        if parent and not os.path.isdir(parent):
            os.makedirs(parent, exist_ok=True)
        # 已存在则跳过，避免破坏目标机器上可能已有的本地修改
        if os.path.exists(dest):
            skipped.append(rel)
            continue
        try:
            with open(dest, "wb") as f:
                f.write(gzip.decompress(base64.b64decode(b64)))
        except OSError as e:
            # 写入失败（如目录不可写）时跳过该文件，不让整个释放中断
            failed.append((rel, str(e)))
            continue
        created.append(rel)
    return created, skipped, failed


def _start(port, no_seed=False):
    """启动服务（直接复用释放出来的 server.py 的 main()）。"""
    here = os.path.dirname(os.path.abspath(__file__))
    os.chdir(here)
    if here not in sys.path:
        sys.path.insert(0, here)
    # server.main() 认「纯数字端口」和 --no-seed，其余本脚本自己的开关丢掉
    argv = [os.path.basename(__file__), str(port)]
    if no_seed:
        argv.append("--no-seed")
    sys.argv = argv
    try:
        import server
    except Exception as e:                      # 释放失败 / 文件被破坏时给一句人话
        _say("[启动] 无法加载 server.py：%s" % e)
        _ask_close()
        return
    try:
        server.main()
    except OSError as e:
        _say("")
        _say("[启动] 启动失败：%s" % e)
        _say("[启动] 端口 %d 可能已被占用 —— 服务是不是已经在另一个窗口里运行了？" % port)
        _say("[启动] 换端口重试：python 工序反馈系统.py 9000")
        _ask_close()


def _ask_close():
    """双击运行时窗口会立刻消失，停一下让人看清错误。"""
    try:
        input("按回车关闭窗口…")
    except (EOFError, KeyboardInterrupt):
        pass


def main():
    args = [a for a in sys.argv[1:]]
    start = "--no-start" not in args
    no_seed = "--no-seed" in args
    port = DEFAULT_PORT
    for a in args:
        if a.isdigit():
            port = int(a)

    here = os.path.dirname(os.path.abspath(__file__))
    created, skipped, failed = _release(here)
    _say("[release] 释放目录：%s" % here)
    if created:
        _say("[release] 新建 %d 个文件：" % len(created))
        for r in created:
            _say("  + " + r)
    if skipped:
        _say("[release] 跳过 %d 个已存在的文件（未覆盖）：" % len(skipped))
        for r in skipped:
            _say("  - " + r)
    if failed:
        _say("[release] %d 个文件写入失败：" % len(failed))
        for r, err in failed:
            _say("  ! %s (%s)" % (r, err))

    if not start:
        _say("")
        hint = "python server.py %d" % port
        if no_seed:
            hint += " --no-seed"
        _say("[启动] 已按要求只释放文件（--no-start）。启动服务请执行：" + hint)
        return

    _say("")
    _start(port, no_seed)


if __name__ == "__main__":
    main()
